//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::utf8_get_fast`; the
//! native twin is `benches/native/Bench/StringUtf8GetFast.lean`.
//! both sides make the program's test that supplies the proof (`atEnd`)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::string;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &PosInput, n: u64) -> u64 {
    let (s, ps) = (inp.s.as_bytes(), &inp.ps[..]);
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let p = nat_unbox(get_word(ps, x >> 52));
            if string::utf8_at_end(s, p) {
                0
            } else {
                u64::from(string::utf8_get_fast(s, p))
            }
        });
    }
    acc
}

fn main() {
    run(|| pos_input(mixed(), Positions::Inside), kernel)
}
